  "source": "def investigate(context, acquire):
    actions = context.get("actions", [])
    max_id = 0
    in_transaction = False
    txn_max_id = -1

    for action in actions:
        op = action["op"]
        if op == "put":
            current_id = action["id"]
            if in_transaction:
                if current_id > txn_max_id:
                    txn_max_id = current_id
            else:
                if current_id > max_id:
                    max_id = current_id
        elif op == "begin":
            if not in_transaction:
                in_transaction = True
                txn_max_id = -1
        elif op == "commit":
            if in_transaction:
                if txn_max_id > max_id:
                    max_id = txn_max_id
                in_transaction = False
                txn_max_id = -1
        elif op == "rollback":
            if in_transaction:
                in_transaction = False
                txn_max_id = -1

    return max_id + 1",
